const BULK_THRESHOLD = 10;
const BULK_DISCOUNT = 0.15;

export function lineTotal(unitPrice, qty) {
  if (!Number.isFinite(unitPrice) || unitPrice < 0) throw new Error('bad unitPrice');
  if (!Number.isInteger(qty) || qty < 0) throw new Error('bad qty');
  const subtotal = unitPrice * qty;
  if (qty > BULK_THRESHOLD) {
    return round2(subtotal * (1 - BULK_DISCOUNT));
  }
  return round2(subtotal);
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { lineTotal } from '../src/pricing.js';

test('small orders pay full price', () => {
  assert.equal(lineTotal(4, 5), 20);
});

test('large orders get the bulk discount', () => {
  assert.equal(lineTotal(10, 20), 170);
});

test('rejects bad quantities', () => {
  assert.throws(() => lineTotal(4, -1));
});

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { cpSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { lineTotal } from '../src/pricing.js';

// 1) Behavior: the boundary is fixed and the neighborhood still holds.
assert.equal(lineTotal(8, 10), 68, 'exactly 10 units must get the bulk discount');
assert.equal(lineTotal(8, 11), 74.8, 'above the threshold keeps the discount');
assert.equal(lineTotal(8, 9), 72, 'below the threshold pays full price');
assert.equal(lineTotal(4, 5), 20, 'small orders unchanged');
console.log('BUGFIX_ORACLE behavior ok');

// 2) Regression guard bites: rebuild the tree with the ORIGINAL seeded
// defect and the test suite must now FAIL - proof that a reproduction
// test exists and would catch a revert. The current tree's suite must
// pass (green after the fix).
const root = process.cwd();
const mutantRoot = join(root, '.oracle-mutant');
rmSync(mutantRoot, { recursive: true, force: true });
mkdirSync(join(mutantRoot, 'src'), { recursive: true });
cpSync(join(root, 'tests'), join(mutantRoot, 'tests'), { recursive: true });
rmSync(join(mutantRoot, 'tests', 'verify-pricing.mjs'), { force: true });
cpSync(join(root, 'package.json'), join(mutantRoot, 'package.json'));
const current = readFileSync(join(root, 'src', 'pricing.js'), 'utf8');
const mutant = current.replace(/qty\s*>=\s*BULK_THRESHOLD/g, 'qty > BULK_THRESHOLD').replace(/qty\s*>=\s*10/g, 'qty > 10');
assert.notEqual(mutant, current, 'could not re-seed the defect - the fix should have made the threshold inclusive');
writeFileSync(join(mutantRoot, 'src', 'pricing.js'), mutant);

function runSuite(cwd) {
  try {
    execFileSync(process.execPath, ['--test'], { cwd, stdio: 'pipe', timeout: 30000 });
    return 0;
  } catch (err) {
    return typeof err.status === 'number' ? err.status : 1;
  }
}

assert.equal(runSuite(root), 0, 'the suite must be green on the fixed tree');
console.log('BUGFIX_ORACLE suite green');
assert.notEqual(runSuite(mutantRoot), 0, 'reverting the fix must make at least one test fail - the regression guard is missing or toothless');
console.log('BUGFIX_ORACLE mutant caught');
const testFiles = readdirSync(join(root, 'tests')).filter((f) => f.endsWith('.mjs') && f !== 'verify-pricing.mjs');
assert.ok(testFiles.length >= 1, 'test layout missing');
console.log('BUGFIX_ORACLE done');
